import{z as r,x as s,o as t,c as d,q as A,j as n,D as e,d as a,s as i,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"对齐数据的去重与清洗","description":"","frontmatter":{"title":"对齐数据的去重与清洗","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ade-dedup-cleaning.md","filePath":"llm/ade-dedup-cleaning.md","lastUpdated":1791413859000}'),D={name:"llm/ade-dedup-cleaning.md"};function p(C,E,m,u,h,F){const l=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=A('<h1 id="对齐数据的去重与清洗" tabindex="-1">对齐数据的去重与清洗 <a class="header-anchor" href="#对齐数据的去重与清洗" aria-label="Permalink to &quot;对齐数据的去重与清洗&quot;">​</a></h1><div class="epigraph"><p>预训练去重防背诵，对齐数据去重防边界悄悄偏移；清洗丢掉的每一类样本，都是一次无声的再配比。</p><footer>—— 据 Lee et al., 2021、Kandpal et al., 2022 与本课程口径整理</footer></div><p><a href="/llm/ade-constitutional-data">上一课</a>把原则变成可编程的生产线，产量不再是瓶颈；产量上来，脏东西一起上来。本课写对齐数据自己的去重与清洗——工具与预训练清洗、合成数据清洗同族（<a href="/llm/synthetic-dedup-contamination">合成数据的去重与污染</a>给过四层去重），但目标不同：防的不是背诵，是边界偏移与验证失真。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三种对齐特有的失效。其一，近重复提示抬高持有集读数：真实日志里用户反复问同一件事，语义近邻横跨训练与持有两侧，验证准确率量到的有一部分是记忆。其二，同簇过密拖偏边界：一个意图簇里数百条近似对，等于给该簇加权数百倍，RM 的容量先拟合它，长尾边界让位。其三，清洗规则与边界打架：毒性提示要不要删？删了，模型从未见过「必须拒绝的题面长什么样」，拒绝边界外移，漏拒与越权一起出问题；隐私清洗要剥的是个人信息，不是危害类别。标签噪声另算：低一致率的对子静默丢弃，丢弃分布不均匀，又是一次再配比。<span class="marginnote">术语先翻译：「持有集」就是刻意留出、不参与训练、专供考试的题库。麻烦在&quot;近邻泄漏&quot;：题库里的题和练习册里的题长得几乎一样（用户换了个说法问同一件事），考出来的高分掺了背诵的水分——验证指标看着漂亮，线上能力却没那么好。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层处理。去重在提示侧与响应侧分开做：精确、MinHash、语义三层照搬，但「同一提示多响应」是资产不是重复——同一 \\(x\\) 下的多个 \\(y\\) 正是偏好对比的信息量；去重的对象是提示簇，簇内保留按差异度预算抽样，与合成侧骨架去重同一招。清洗分三类记账：隐私剥离（PII、联系方式）照删；毒性提示保留，过政策映射后入库——它们是拒绝边界的定义样本；越权对照对（红队课的疫苗）显式保护，任何清洗规则不得顺手删掉它们。噪声处理不静默：低一致率对子走仲裁或降权（<a href="/llm/annotation-agreement">标注一致性与仲裁</a>的口径），丢弃必须记账——丢弃分布写进数据卡，与保留分布并排。</p>',7)),(t(),n(o,null,{default:e(()=>[i(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E6%B7%B7%E5%90%88%E6%B1%A0%22%5D%20--%3E%20DEDUP%5B%22%E6%8F%90%E7%A4%BA%E7%B0%87%E5%8E%BB%E9%87%8D%EF%BC%9A%E4%B8%89%E5%B1%82%20%2B%20%E5%B7%AE%E5%BC%82%E5%BA%A6%E9%A2%84%E7%AE%97%22%5D%0A%20%20DEDUP%20--%3E%20CLEAN%7B%22%E5%88%86%E7%B1%BB%E5%A4%84%E7%BD%AE%22%7D%0A%20%20CLEAN%20--%3E%7C%22PII%20%2F%20%E8%81%94%E7%B3%BB%E6%96%B9%E5%BC%8F%22%7C%20DROP%5B%22%E5%89%A5%E7%A6%BB%E4%B8%A2%E5%BC%83%22%5D%0A%20%20CLEAN%20--%3E%7C%22%E6%AF%92%E6%80%A7%E6%8F%90%E7%A4%BA%22%7C%20KEEP%5B%22%E4%BF%9D%E7%95%99%EF%BC%9A%E6%94%BF%E7%AD%96%E6%98%A0%E5%B0%84%E5%90%8E%E5%85%A5%E5%BA%93%22%5D%0A%20%20CLEAN%20--%3E%7C%22%E8%B6%8A%E6%9D%83%E5%AF%B9%E7%85%A7%E5%AF%B9%22%7C%20PROTECT%5B%22%E6%98%BE%E5%BC%8F%E4%BF%9D%E6%8A%A4%22%5D%0A%20%20CLEAN%20--%3E%7C%22%E4%BD%8E%E4%B8%80%E8%87%B4%E7%8E%87%22%7C%20ARB%5B%22%E4%BB%B2%E8%A3%81%20%2F%20%E9%99%8D%E6%9D%83%22%5D%0A%20%20DROP%20--%3E%20CARD%5B%22%E6%95%B0%E6%8D%AE%E5%8D%A1%EF%BC%9A%E4%BF%9D%E7%95%99%E4%B8%8E%E4%B8%A2%E5%BC%83%E5%88%86%E5%B8%83%E5%B9%B6%E6%8E%92%22%5D%0A%20%20KEEP%20--%3E%20CARD%0A%20%20PROTECT%20--%3E%20CARD%0A%20%20ARB%20--%3E%20CARD%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("去重目标为什么不同：预训练的重复经似然损失放大成背诵；对齐数据的重复经对比损失放大成「最便宜可分特征在高频簇上的拟合」——重复给簇加权，加权把 RM 的判别边界拉向该簇的局部特征。持有集失真的机制是近邻泄漏：去重阈值就是泄漏检测的阈值，两端要用同一把尺。清洗即再配比的机制，合成课说过一遍，这里再钉一次：每条丢弃规则作用于分布的不均匀子集，删完分布就变了——所以要看被保留集合的意图分布相对原分布移动了多少，不看删了多少条（"),B("a",{href:"/llm/synthetic-quality-filter"},"质量过滤：打分器与一致性"),a("「过滤即重加权」的口径）。")],-1)),(t(),n(o,null,{default:e(()=>[i(l,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20CL%5B%22%E5%90%8C%E4%B8%80%E6%84%8F%E5%9B%BE%E7%B0%87%E6%95%B0%E7%99%BE%E6%9D%A1%E8%BF%91%E4%BC%BC%E5%AF%B9%22%5D%20--%3E%20W%5B%22%E7%AD%89%E4%BA%8E%E7%BB%99%E8%AF%A5%E7%B0%87%E5%8A%A0%E6%9D%83%E6%95%B0%E7%99%BE%E5%80%8D%22%5D%0A%20%20W%20--%3E%20FIT%5B%22RM%20%E5%AE%B9%E9%87%8F%E5%85%88%E6%8B%9F%E5%90%88%E9%AB%98%E9%A2%91%E7%B0%87%22%5D%0A%20%20FIT%20--%3E%20SHIFT%5B%22%E5%88%A4%E5%88%AB%E8%BE%B9%E7%95%8C%E6%8B%89%E5%90%91%E8%AF%A5%E7%B0%87%E5%B1%80%E9%83%A8%E7%89%B9%E5%BE%81%22%5D%0A%20%20SHIFT%20--%3E%20TAIL%5B%22%E9%95%BF%E5%B0%BE%E6%84%8F%E5%9B%BE%E8%BE%B9%E7%95%8C%E8%AE%A9%E4%BD%8D%EF%BC%8C%E5%88%A4%E9%94%99%22%5D%0A%20%20FIX%5B%22%E5%B7%AE%E5%BC%82%E5%BA%A6%E9%A2%84%E7%AE%97%E6%8A%BD%E6%A0%B7%E6%8E%A7%E7%B0%87%E5%AF%86%E5%BA%A6%22%5D%20--%3E%20W%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">数字感受一下&quot;加权&quot;：某常用意图簇有 500 条近似对，而某个长尾意图只有 5 条——仅凭条数，前者在训练里的话语权就是后者的 100 倍。RM 参数有限，先学会的分界自然是那条被重复 100 次的边界，长尾意图的&quot;对错线&quot;被挤到没人管的角落，评测一覆盖长尾就露馅。</span></p><p><span class="marginnote">最容易错手的一条规则：「删掉所有含敏感词的提示」。它删掉的恰好是拒绝边界最需要的定义样本——删完之后安全分数好看（没题可错），线上漏拒率上涨。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>去重不解决标注噪声，那是仲裁的题；语义去重的阈值是超参，错删边界对子的代价高于留几条重复。清洗规则要按「特征」审查而不按「内容」审查：按长度删、按格式删都会变成隐性配比。上游与下游的接口在下一课：清洗守的是单条质量与簇密度，配比守的是池与格子的形状——本课交付的是一份带丢弃记账的干净池，不是一份配平的池。<span class="marginnote">常见误区：把&quot;干净&quot;理解成&quot;删得越狠越好&quot;。对齐数据里删错的代价不对称——多留几条重复只是浪费一点容量，错删一条定义拒绝边界的毒性提示或越权对照对，就是悄悄挪了一次安全边界。所以阈值要偏保守，宁可疑而保留，记账后再审。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对齐去重防的是边界偏移与持有集失真，不是背诵；去重在提示簇层做，同题多响应是资产。</li><li>清洗分三类：隐私照删，毒性提示保留（它们定义拒绝边界），对照对显式保护。</li><li>噪声不静默丢弃：仲裁或降权，丢弃分布与保留分布并排写进数据卡。</li><li>清洗即再配比：看保留集合的分布移动，不看删除条数。</li><li>出处：Lee et al., 2021；Kandpal et al., 2022；四层去重与过滤口径见合成数据课。</li></ul>',6))])}const _=r(D,[["render",p]]);export{f as __pageData,_ as default};
